@lisp.sf("let*")
def _sf_let_star(xs, env, sfs):
    binds, *body = xs
    for name, val in binds:
        env = env.new_frame({name.s: scm_eval_tco(val, env, sfs)})
    return Thunk(_body_expr(body), env)

