@lisp.sf()
def _sf_letrec(xs, env, sfs):
    binds, *body = xs
    new_env = env.new_frame({name.s: None for name, _ in binds})
    for name, val in binds: new_env[name.s] = scm_eval_tco(val, new_env, sfs)
    return Thunk(_body_expr(body), new_env)

